95fc121ddf21899b39a8dfe1dbc811df5d51607a:
# Public: drawing fields of one form. A private form is null for a visitor.
query FlxForm($id: ID!) {
  flxForm(id: $id) {
    id
    title
    formType
    steps
    buttonLabel
    successTitle
    successMessage
    fields {
      id
      type
      label
      required
      placeholder
      options {
        value
        label
      }
    }
  }
}

63ecf964a1b0c38a2c67ef1718868b9f2738ccb5:
# Public: send a form, survey or subscribe form.
mutation FlxFormSubmit($input: FlxFormSubmitInput!) {
  flxFormSubmit(input: $input) {
    submission {
      id
      trackCode
    }
    errors {
      code
      message
      field
    }
  }
}

811ba106ed088189dc4b8cb8b6c27bed619e102d:
# Public: open a submission with its tracking code.
query FlxFormTrack($code: String!) {
  flxFormTrack(code: $code) {
    trackCode
    formTitle
    submittedAt
    fields {
      label
      value
    }
    replies {
      body
      createdAt
    }
  }
}

835f1a50e0248f54185306acb89d8fb632be7281:
# Public: reply on a tracked submission. Attachments must be reserved for that ticket.
mutation FlxFormTrackReply($input: FlxFormTrackReplyInput!) {
  flxFormTrackReply(input: $input) {
    submission {
      id
      trackCode
    }
    errors {
      code
      message
      field
    }
  }
}
